def sum_common_divisors(a, b):
    # Find GCD
    from math import gcd
    g = gcd(a, b)

    # Find all divisors of g
    divisors = set()
    for i in range(1, int(g**0.5) + 1):
        if g % i == 0:
            divisors.add(i)
            divisors.add(g // i)

    return sum(divisors)

