def max_bitonic_sum(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == j:
                dp[i][j] = arr[i]
            else:
                # Check if arr[i] > arr[j]
                if arr[i] > arr[j]:
                    dp[i][j] = max(dp[i][j], dp[i-1][j-1] + arr[i])
                else:
                    dp[i][j] = max(dp[i][j], dp[i][j-1])

    # Now, find the maximum sum of a bitonic subsequence
    max_sum = 0
    for i in range(n):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                max_sum = max(max_sum, dp[i][j])

    return max_sum

# Test the function
assert max_sum([1, 15, 51, 45, 33, 100, 12, 18, 9]) == 194

