def max_product_in_increasing_subsequence(nums):
    n = len(nums)
    dp = [0] * n
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] * nums[i])
    return max(dp)

